import numpy as np
import mujoco
from scipy.spatial.transform import Rotation

class Controller:
    def __init__(self,s):
        self.s=s; self.m=s.model
        self.kd=mujoco.MjData(self.m)
        self.qa=np.array([self.m.joint(f'robot0_joint{i}').qposadr[0] for i in range(1,8)])
        self.da=np.array([self.m.joint(f'robot0_joint{i}').dofadr[0] for i in range(1,8)])
        self.lim=np.array([self.m.joint(f'robot0_joint{i}').range for i in range(1,8)])
        self.site=self.m.site('gripper0_right_grip_site').id
        self.hj=self.m.joint('sink_left_group_handle_joint').qposadr[0]
        self.hgeom=self.m.geom('sink_left_group_handle_main').id
        self.jp=np.zeros((3,self.m.nv)); self.jr=np.zeros((3,self.m.nv))
    def pose(self):
        return self.s.data.site_xpos[self.site].copy(), self.s.data.site_xmat[self.site].reshape(3,3).copy()
    def ik(self,p,R=None,q=None, n=150):
        self.kd.qpos[:]=self.s.data.qpos
        if q is None: q=self.s.data.qpos[self.qa].copy()
        for _ in range(n):
            self.kd.qpos[self.qa]=q
            mujoco.mj_forward(self.m,self.kd)
            ep=np.asarray(p)-self.kd.site_xpos[self.site]
            if R is not None:
                er=Rotation.from_matrix(R@self.kd.site_xmat[self.site].reshape(3,3).T).as_rotvec()
            else: er=np.zeros(3)
            err=np.r_[ep,er*.4]
            if np.linalg.norm(err)<1e-5: break
            mujoco.mj_jacSite(self.m,self.kd,self.jp,self.jr,self.site)
            J=np.vstack((self.jp[:,self.da],self.jr[:,self.da]*.4)) if R is not None else np.vstack((self.jp[:,self.da],self.jr[:,self.da]*0))
            dq=J.T@np.linalg.solve(J@J.T+np.eye(6)*1e-4,err)
            q=np.clip(q+np.clip(dq,-.08,.08),self.lim[:,0]+.005,self.lim[:,1]-.005)
        return q, np.linalg.norm(ep),np.linalg.norm(er)
    def step(self,q,grip=-1,base=None,torso=0):
        a=np.zeros(13); a[:7]=q; a[7]=grip; a[11]=torso; a[12]=-1
        if base is not None: a[8:11]=base; a[12]=1
        return self.s.step(a)
    def move(self,p,R=None,steps=100,grip=-1,log=20):
        start,rs=self.pose()
        if R is None: R=rs
        q=self.s.data.qpos[self.qa].copy()
        for i in range(steps):
            f=(i+1)/steps
            target=start+(np.asarray(p)-start)*f
            q,e,er=self.ik(target,R,q,n=30)
            self.step(q,grip)
            if log and ((i+1)%log==0 or i==steps-1): print('move',len(self.s.actions),'p',self.pose()[0],'err',e,er,'handle',self.s.data.qpos[self.hj],flush=True)
        return self.s.check()
    def hold(self,n=20,grip=-1):
        q=self.s.targets[:7].copy()
        for _ in range(n): self.step(q,grip)
        print('hold',self.s.check(),'handle',self.s.data.qpos[self.hj],flush=True)
    def contacts(self):
